INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A clavícula é o primeiro osso a se ossificar no corpo humano. Qual a função mecânica mais importante deste osso na cintura escapular?","options":{"a":"Proteger os vasos caróticos.","b":"Atuar como um suporte (suporte) que mantém o membro superior afastado do tronco.","c":"Permitir a rotação da cabeça.","d":"Suportar o peso do pulmão.","e":"Não possui função mecânica relevante."},"answer":"b","rationale":"A clavícula transmite o peso e as forças do membro superior para o esqueleto axial e mantém a escápula em posição lateral.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia funcional do membro superior.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Osteologia"]}', 'b0ede95db3c0943d16c01e141a62808e', 350, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''manguito rotador'' é um grupo de quatro músculos que estabilizam a articulação glenoumeral. Qual desses músculos é o único que realiza ROTAÇÃO MEDIAL (interna) do úmero?","options":{"a":"Supraespinal.","b":"Infraespinal.","c":"Redondo menor.","d":"Subescapular.","e":"Redondo maior."},"answer":"d","rationale":"O subescapular insere-se no tubérculo menor e é um potente rotador medial. Os outros (exceto o supraespinal que abduz) são rotadores laterais.","option_rationales":{"a":"Errada. Inicia a abdução.","b":"Errada. Rotação lateral.","c":"Errada. Rotação lateral.","d":"Correta. Miologia funcional do ombro.","e":"Errada. Não faz parte do manguito rotador (apesar da ação similar)."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Miologia"]}', 'd040c4f620182d8b024e7c727d257931', 351, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Uma lesão no ''nervo torácico longo'' (C5-C7) resulta em uma deformidade característica conhecida como ''escápula alada''. Qual músculo está paralisado nessa condição?","options":{"a":"Trapézio.","b":"Romboides.","c":"Serrátil anterior.","d":"Latíssimo do dorso.","e":"Peitoral maior."},"answer":"c","rationale":"O serrátil anterior mantém a borda medial da escápula contra a parede torácica. Sua paralisia faz com que a escápula se descole posteriormente.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Neurologia periférica aplicada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Neuroanatomia/Miologia"]}', '1607b9f19455ecad3388d423160ecfe3', 352, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''artéria axilar'' é dividida em três partes pelo músculo peitoral menor. Qual artéria é o ramo mais importante da SEGUNDA parte da axilar?","options":{"a":"Artéria torácica superior.","b":"Artéria toracoacromial.","c":"Artéria torácica lateral.","d":"Artéria subescapular.","e":"Artérias circunflexas do úmero."},"answer":"b","rationale":"A segunda parte (atrás do músculo) emite a toracoacromial e a torácica lateral.","option_rationales":{"a":"Errada. Ramo da 1ª parte.","b":"Correta. Vascularização da região axilar.","c":"Errada. Também é da 2ª parte, mas a toracoacromial costuma ser mais cobrada por seus troncos.","d":"Errada. Ramo da 3ª parte.","e":"Errada. Ramos da 3ª parte."},"difficulty":"Difícil","tags":["Anatomia","Membro Superior","Angiologia"]}', 'c84f2a001a36cf94ad6067a8356f8528', 353, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O plexo braquial é formado pelos ramos anteriores de C5 a T1. Qual ''cordão'' (fascículo) do plexo braquial dá origem aos nervos ulnar e à raiz medial do nervo mediano?","options":{"a":"Cordão Lateral.","b":"Cordão Medial.","c":"Cordão Posterior.","d":"Tronco Superior.","e":"Divisão Anterior."},"answer":"b","rationale":"O cordão medial é a continuação do tronco inferior e fornece inervação para os músculos flexores da mão e intrínsecos ulnares.","option_rationales":{"a":"Errada. Dá origem ao musculocutâneo e raiz lateral do mediano.","b":"Correta. Organização do plexo braquial.","c":"Errada. Dá origem ao axilar e radial.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Neuroanatomia"]}', 'fe1af780f23ed93703ca5748c685a39d', 354, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Em uma fratura do ''colo cirúrgico'' do úmero, qual nervo e arteria correm maior risco de lesão traumática?","options":{"a":"Nervo radial e artéria braquial profunda.","b":"Nervo axilar e artéria circunflexa posterior do úmero.","c":"Nervo ulnar e artéria braquial.","d":"Nervo mediano e artéria axilar.","e":"Nervo musculocutâneo."},"answer":"b","rationale":"Essas estruturas atravessam o espaço quadrangular logo abaixo da articulação, contornando o colo cirúrgico.","option_rationales":{"a":"Errada. Risco em fraturas da diáfise (sulco do nervo radial).","b":"Correta. Anatomia aplicada ao trauma ortopédico.","c":"Errada. Risco em fraturas do epicôndilo medial.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Topografia/Osteologia"]}', 'dc4d132f22fc98419bd1240b45803734', 355, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo bíceps braquial'' possui duas cabeças. Onde se insere o TENDÃO LONGO do bíceps no esqueleto?","options":{"a":"Processo coracoide da escápula.","b":"Tubérculo supraglenoidal da escápula.","c":"Tubérculo infraglenoidal da escápula.","d":"Acrômio.","e":"Epicôndilo lateral do úmero."},"answer":"b","rationale":"A cabeça longa do bíceps é intracapsular e origina-se no tubérculo supraglenoidal.","option_rationales":{"a":"Errada. Origem da cabeça curta.","b":"Correta. Miologia do braço.","c":"Errada. Origem da cabeça longa do tríceps.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Miologia"]}', 'e3975124d21e86a22267dbee61ccd0ae', 356, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''veia cefálica'' é um acesso venoso comum. Qual o seu trajeto superficial e onde ela desemboca?","options":{"a":"Sobe pelo lado medial do braço; desemboca na veia braquial.","b":"Sobe pelo lado lateral do braço, no sulco deltopeitoral; desemboca na veia axilar.","c":"Sobe pelo centro do braço; desemboca na veia jugular.","d":"É uma veia profunda do antebraço.","e":"Desemboca diretamente na veia cava superior."},"answer":"b","rationale":"A veia cefálica percorre o sulco deltopeitoral e perfura a fáscia clavipectoral para atingir a veia axilar.","option_rationales":{"a":"Errada. Descrição da veia basílica.","b":"Correta. Drenagem venosa superficial do membro superior.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Angiologia"]}', 'a5e47d8d2eda4c34f5d334d79cbadbae', 357, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo braquial'' situa-se profundamente ao bíceps. Qual a sua principal ação biomecânica?","options":{"a":"Supinação do antebraço.","b":"Flexão do antebraço em todas as posições (é o flexor puro).","c":"Extensão do cotovelo.","d":"Adução do braço.","e":"Pronação do antebraço."},"answer":"b","rationale":"Diferente do bíceps, que depende da supinação para flexionar com força, o braquial é o principal flexor do cotovelo independente da posição da mão.","option_rationales":{"a":"Errada. Função do bíceps e supinador.","b":"Correta. Biomecânica muscular do cotovelo.","c":"Errada. Função do tríceps.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Miologia"]}', '97705d4e45e54b44979cb3299415c54a', 358, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''espaço triangular'' (triângulo dos redondos) é um marco anatômico na região posterior do ombro. Qual estrutura atravessa este espaço?","options":{"a":"Nervo axilar.","b":"Artéria circunflexa da escápula.","c":"Nervo radial.","d":"Artéria braquial profunda.","e":"Veia cefálica."},"answer":"b","rationale":"O espaço triangular é delimitado pelos músculos redondo menor, redondo maior e cabeça longa do tríceps. Contém os vasos circunflexos da escápula.","option_rationales":{"a":"Errada. Passa pelo espaço quadrangular.","b":"Correta. Topografia regional do ombro.","c":"Errada. Passa pelo intervalo triangular (inferior).","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Membro Superior","Topografia"]}', 'ef24f1961324faf94119a410e7e6920c', 359, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual dos seguintes ossos do carpo é o mais comumente fraturado após queda com a mão espalmada?","options":{"a":"Semilunar.","b":"Escafoide.","c":"Piramidal.","d":"Hamatum.","e":"Pisiforme."},"answer":"b","rationale":"O escafoide é frequentemente lesado e tem risco de necrose avascular devido ao seu suprimento sanguíneo retrógrado.","option_rationales":{"a":"Errada. Mais comum em luxações.","b":"Correta. Patologia traumática da mão.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Osteologia"]}', 'a26215ab6ffe593d7e2d8f40649a8e95', 360, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''ligamento anular do rádio'' mantém a cabeça do rádio contra a incisura radial da ulna. Qual a importância clínica deste ligamento em crianças pequenas (subluxação da cabeça do rádio)?","options":{"a":"O rádio rompe as fibras do ligamento.","b":"A cabeça do rádio escorrega por dentro do ligamento imaturo ao ser puxada pelo braço.","c":"O ligamento calcifica precocemente.","d":"Impede o crescimento do braço.","e":"Causa paralisia do nervo ulnar."},"answer":"b","rationale":"Conhecido como ''cotovelo da babá'', ocorre quando a criança é puxada subitamente pelo punho.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia aplicada à pediatria/ortopedia.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Artrologia/Pediatria"]}', '2f1e770aa71ffb6c5e8b9ec6c3c8f2bb', 361, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''fossa cubital'' é uma região triangular na face anterior do cotovelo. Qual a estrutura mais MEDIAL contida nesta fossa?","options":{"a":"Nervo radial.","b":"Tendão do bíceps braquial.","c":"Artéria braquial.","d":"Nervo mediano.","e":"Nervo musculocutâneo."},"answer":"d","rationale":"De lateral para medial: Nervo radial (sob o braquiorradial), Tendão do bíceps, Artéria braquial, Nervo mediano.","option_rationales":{"a":"Errada. É o mais lateral.","b":"Errada. Central.","c":"Errada. Entre o tendão e o nervo.","d":"Correta. Conteúdo da fossa cubital.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Topografia"]}', '1c06845bb8ba7f134e67990ccfe86315', 362, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo ulnar'' passa por trás do cotovelo em uma região onde é facilmente atingido ou comprimido. Que marco ósseo define esse local?","options":{"a":"Olecrano.","b":"Epicôndilo medial do úmero.","c":"Epicôndilo lateral do úmero.","d":"Processo coronoide.","e":"Cabeça do rádio."},"answer":"b","rationale":"O nervo ulnar corre no sulco do nervo ulnar, posterior ao epicôndilo medial.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia de superfície e compressão nervosa.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Osteologia/Neuroanatomia"]}', 'ca746ef8f0cf8b495286902dba68bcec', 363, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''canal do carpo'' é delimitado pelos ossos do carpo e pelo retináculo dos flexores. Qual nervo é comprimido na Síndrome do Túnel do Carpo?","options":{"a":"Nervo ulnar.","b":"Nervo radial.","c":"Nervo mediano.","d":"Nervo musculocutâneo.","e":"Nervo axilar."},"answer":"c","rationale":"O nervo mediano passa pelo túnel junto com 9 tendões flexores.","option_rationales":{"a":"Errada. Passa pelo canal de Guyon.","b":"Errada. Não entra na mão pelo túnel do carpo.","c":"Correta. Patologia compressiva mais comum do membro superior.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Neuroanatomia/Clínica"]}', '25e71db3b4e9957c31679f1e60317fd9', 364, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo ''oponente do polegar'' permite a pinça fina da mão. Qual nervo inerva a maioria dos músculos da eminência TENAR (incluindo o oponente)?","options":{"a":"Nervo radial.","b":"Nervo ulnar.","c":"Nervo mediano (ramo recorrente).","d":"Nervo musculocutâneo.","e":"Fibras de T1 apenas."},"answer":"c","rationale":"A eminência tenar é essencialmente território do nervo mediano, exceto pela cabeça profunda do flexor curto e o adutor.","option_rationales":{"a":"Errada.","b":"Errada. Inerva a eminência hipotenar.","c":"Correta. Inervação motora da mão.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Neuroanatomia"]}', '66c6f322aaf02a140c38b35b0fb48948', 365, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''tabaqueira anatômica'' é uma depressão lateral no punho. Quais tendões delimitam a sua borda POSTERIOR (medial)?","options":{"a":"Extensor curto do polegar e abdutor longo do polegar.","b":"Extensor longo do polegar.","c":"Braquiorradial.","d":"Flexor radial do carpo.","e":"Extensor dos dedos."},"answer":"b","rationale":"A borda lateral é formada pelo extensor curto e abdutor longo. A borda medial (posterior na posição anatômica) é o extensor longo do polegar.","option_rationales":{"a":"Errada. Formam a borda lateral (anterior).","b":"Correta. Marco anatômico de superfície no punho.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Membro Superior","Miologia/Superfície"]}', '46e980b6f88b6e33d91a2b5cd5624ff3', 366, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo musculocutâneo'' (C5-C7) perfura qual músculo ao entrar no compartimento anterior do braço?","options":{"a":"Bíceps braquial.","b":"Braquial.","c":"Coracobraquial.","d":"Deltoide.","e":"Tríceps braquial."},"answer":"c","rationale":"Após perfurar o coracobraquial, o nervo corre entre o bíceps e o braquial, inervando todos os flexores do braço.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Trajeto nervoso do plexo braquial.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Neuroanatomia"]}', 'd14d2e70b11b82fa552fd9be887473fa', 367, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"No antebraço, qual músculo é responsável pela PRONAÇÃO e situa-se na camada mais PROFUNDA de flexores em relação ao punho?","options":{"a":"Pronador redondo.","b":"Pronador quadrado.","c":"Flexor superficial dos dedos.","d":"Supinador.","e":"Braquiorradial."},"answer":"b","rationale":"O pronador quadrado é o músculo mais profundo da face anterior do antebraço distal.","option_rationales":{"a":"Errada. É o flexor mais superficial e proximal.","b":"Correta. Miologia do antebraço.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Miologia"]}', '6c04f7bf9afec6caf035086648e82369', 368, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''arteria braquial'' é a continuação da axilar. Onde ela costuma se bifurcar em artérias radial e ulnar?","options":{"a":"No meio do braço.","b":"Na fossa cubital, ao nível do colo do rádio.","c":"No punho.","d":"Atrás do epicôndilo medial.","e":"Na axila."},"answer":"b","rationale":"A bifurcação ocorre no ápice da fossa cubital, sob a aponeurose bicipital.","option_rationales":{"a":"Errada.","b":"Correta. Vascularização do membro superior.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Angiologia"]}', '16fa21534669126f1f0a6f0123f6270b', 369, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo radial'' inerva todos os músculos de qual compartimento do membro superior?","options":{"a":"Anterior do braço e antebraço.","b":"Posterior do braço e antebraço.","c":"Medial da mão.","d":"Lateral do braço.","e":"Anterior do antebraço."},"answer":"b","rationale":"O nervo radial é o nervo da ''extensão'' (tríceps e extensores do punho/dedos).","option_rationales":{"a":"Errada.","b":"Correta. Regra geral de inervação motora.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Neuroanatomia"]}', 'f1f0a29aeec0801bc69ddb71855e5881', 370, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo lumbricais'' da mão têm uma origem anatômica incomum. Onde eles se originam?","options":{"a":"Nos ossos metacarpais.","b":"Nos tendões do músculo flexor profundo dos dedos.","c":"No rádio.","d":"No retináculo dos flexores.","e":"Nos ossos do carpo."},"answer":"b","rationale":"Os lumbricais originam-se nos tendões do flexor profundo e se inserem na expansão extensora dos dedos.","option_rationales":{"a":"Errada. Origem dos interósseos.","b":"Correta. Miologia intrínseca da mão.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Membro Superior","Miologia"]}', '4cc3c2ac0f62e0425d73d473a0acddcd', 371, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um paciente apresenta ''mão em garra'' (hiperextensão das metacarpofalângicas e flexão das interfalângicas) nos 4º e 5º dedos. Qual nervo foi lesado?","options":{"a":"Nervo mediano.","b":"Nervo ulnar.","c":"Nervo radial.","d":"Nervo axilar.","e":"Nervo musculocutâneo."},"answer":"b","rationale":"A paralisia dos lumbricais mediais e interósseos pelo nervo ulnar causa este desequilíbrio muscular.","option_rationales":{"a":"Errada. Causa ''mão de pregador'' ou ''mão simiesca''.","b":"Correta. Neurologia clínica do membro superior.","c":"Errada. Causa ''mão caída''.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Neuroanatomia/Clínica"]}', '72085efb806947e8a7c261d5641228bd', 372, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''arco palmar PROFUNDO'' é formado principalmente pela terminação de qual artéria?","options":{"a":"Artéria ulnar.","b":"Artéria radial.","c":"Artéria interóssea anterior.","d":"Artéria braquial.","e":"Artéria digital comum."},"answer":"b","rationale":"Diferente do arco superficial (principalmente ulnar), o arco profundo é a continuação da artéria radial após passar pela tabaqueira.","option_rationales":{"a":"Errada. Forma o arco superficial.","b":"Correta. Vascularização da mão.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Angiologia"]}', '30af2d7718006da95c80780e163c3a6e', 373, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''escápula'' possui uma projeção anterior em forma de bico de pássaro. Como se chama essa estrutura onde se inserem o peitoral menor e a cabeça curta do bíceps?","options":{"a":"Acrômio.","b":"Processo coracoide.","c":"Espinha da escápula.","d":"Glenoide.","e":"Ângulo inferior."},"answer":"b","rationale":"O processo coracoide é um marco palpável importante para bloqueios do plexo braquial e cirurgia de ombro.","option_rationales":{"a":"Errada. Projeção posterior e superior.","b":"Correta. Osteologia da escápula.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Membro Superior","Osteologia"]}', '1923904f2fef7112eeefdc7c98d5273d', 374, 'draft');